lemma rep_mul_pair (g : GaugeGroupI) {ι κ : Type} [Fintype ι] [Fintype κ]
    {X : ι → fieldData.LocalCovFieldAlgebra} {Y : κ → fieldData.LocalCovFieldAlgebra} {x₀ : ι}
    {y₀ : κ} {cX : ι → ℂ} {cY : κ → ℂ}
